        content:
          "전립선비대증 치료에 쓰는 피나스테리드 5mg 전문의약품으로, 식약처 허가 기준에 근거해 처방되는 약이에요. 비대해진 전립선이 요도를 눌러 소변 줄기가 약해지거나 야간뇨·잔뇨감이 심할 때, 피나스테리드 5mg이 작용해 증상을 개선해줘요.\n\n성분인 피나스테리드는 5α-환원효소 2형을 억제해 테스토스테론이 DHT로 전환되는 걸 막아요. DHT가 줄면 비후된 전립선이 점차 퇴행하면서 소변 흐름이 개선되죠. 식약처 허가 효능에는 증상 개선, 전립선 퇴행 및 요류 개선, 급성 요폐 발생빈도 감소, 전립선 경요도 절제술 및 수술 필요성 감소가 명시돼 있어요.\n\n효과가 빠르게 나타나지 않는다는 점도 알아두세요. 허가사항에 '증상이 개선되더라도 최소 6개월간의 치료가 필요하다'고 명확히 적혀 있거든요. 4년간 임상에서 1,524명을 추적했는데, 단기간 복용으로는 평가 자체가 어렵고 꾸준히 복용하면서 비뇨기과에서 정기 확인을 받는 게 기준이에요.\n\n탈모 목적으로 피나스테리드를 찾는다면 알파스카정은 5mg 제품이라 탈모 치료 허가 대상이 아니에요. 탈모 치료엔 피나스테리드 1mg 허가 제품으로 처방받아야 하죠. 꾸준함이 핵심이에요. 남성형 탈모로 모발 고민을 하다 이 약을 접한 분도 많지만, 탈모 치료 목적이라면 짚어야 할 게 있어요.",
