        "content": "식약처 의약품동등성시험 정보가 이 질문의 답이에요. 이 약과 같은 원료를 사용하고 동일한 제조방법으로 만든 피나스테리드 1mg(모나스타정1밀리그램)을 오리지널 대조약 프로페시아정1밀리그램과 2×2 교차시험으로 건강한 성인 25명에게 단회 경구투여해 혈중 피나스테리드를 측정했어요.\n\n결과를 보면 동등성의 근거가 분명해요. 비교평가항목인 AUC와 Cmax를 로그변환해 통계처리했을 때 평균치 차의 90% 신뢰구간이 log 0.8에서 log 1.25 이내였거든요. 구체적으로 AUC는 log 0.9303~1.0495, Cmax는 log 0.9475~1.0514로 동등성 기준 안에 들어와 생물학적으로 동등함이 입증됐죠. 흡수되는 양과 속도가 오리지널과 통계적으로 같다는 의미예요.\n\n그래서 효과를 보는 기준도 같아요. 식약처 허가사항은 일반적으로 3개월 이상 복용해야 치료효과를 볼 수 있다고 안내하는데, 이 기준은 오리지널이든 동등성을 입증한 제품이든 동일하게 적용되죠. 동등성시험은 효과 발현을 빠르게 해주는 게 아니라, 같은 성분이 같은 양만큼 흡수된다는 걸 보장하는 검사예요.",
