    "description": "모그로정 1밀리그램은 피나스테리드 1mg 제네릭으로, 식약처가 만 18~41세 남성형 탈모증 치료에 허가한 전문의약품이에요. 효과 발현 시점과 1일 1정 복용법, 임상 부작용, 28정 16,000원 기준가까지 정리했어요.",
    "heroDescription": "모그로정을 받아 들고 가장 먼저 드는 생각은 \"이거 언제부터 듣나\"일 거예요. 피나스테리드 1mg 제네릭으로, 식약처가 만 18~41세 남성형 탈모증에 허가한 전문의약품이에요. 허가 용법상 보통 3개월은 넘게 먹어야 변화가 보여요. 28정 기준가는 16,000원, 한 알로 치면 571원쯤이고요. 효과 시점부터 부작용, 가격까지 차례로 풀게요.",
