      "프리피나정(피나스테리드 5mg)은 진양제약의 전립선비대증 전문의약품이다. 식약처 허가 적응증, 1일 1회 복용법, 28정 기준 가격과 동일 성분 제네릭 92종 중 순위를 정리했다.",
    description:
      "프리피나정(피나스테리드 5mg)은 진양제약의 전립선비대증 전문의약품이다. 식약처 허가 적응증, 1일 1회 복용법, 28정 기준 가격과 동일 성분 제네릭 ",
    heroDescription:
      "전립선비대증 치료제를 처방받고 나서 처음 드는 질문이 있죠. '이 약이 맞는 건지, 얼마나 먹어야 하는지, 가격은 적당한지.' 프리피나정은 진양제약이 만드는 피나스테리드 5mg 전문의약품이에요. 식약처 허가 적응증은 양성전립샘비대증 — 증상 개선, 비후된 전립샘 퇴행, 요류 개선, 급성 요폐 예방, 수술 필요성 감소가 허가 기준에 포함돼요. 탈모 목적이라면 피나스테리드 1mg으로 별도 처방을 받아야 해요.",
