          "전립선이 비대해지면 소변 흐름이 방해를 받아요. 일양피나스테리드정의 식약처 허가 적응증은 양성전립샘비대증이에요. 허가 기준이 인정하는 효능은 네 가지예요.\n\n첫째 양성전립샘비대증 증상의 개선, 둘째 비후된 전립샘의 퇴행 및 요류 개선, 셋째 급성 요폐의 발생빈도 감소, 넷째 전립샘 경요도 절제술(Transurethral Resection of the Prostate)을 포함한 수술의 필요성 감소고요. 허가 등록 정보 그대로예요.\n\n피나스테리드는 5α-환원효소 2형을 억제해 테스토스테론이 DHT로 전환되는 것을 막아요. DHT가 전립선 세포 증식을 촉진하는 주요 물질이라, 이를 줄이면 비대해진 전립선이 점차 퇴행하면서 배뇨 증상이 개선돼요. 탈모 목적으로 이 약을 찾는 분도 있는데, 일양피나스테리드정 5mg은 탈모 적응증이 없어요. 탈모 치료라면 피나스테리드 1mg으로 허가받은 별도 제품을 처방받아야 해요.",
