          "허가 용법은 피나스테리드로서 1일 1회 5mg을 식사와 관계없이 경구투여해요. 복용 시 증상이 개선되더라도 최소 6개월간의 치료가 필요하다고 식약처 허가사항이 명시하고 있어요.\n\n신부전 환자와 고령자는 용량 조절이 필요 없어요. 허가 문서에 따르면 크레아티닌청소율이 9.0 mL/min인 환자에서도 약물동력학적 변화가 없었고, 70세 이상 고령자에서 배설이 약간 감소하나 용량 조절 기준에 해당하지 않아요.\n\n한 가지 반드시 확인할 사항이 있어요. 5mg은 전립선비대증 허가 용량이에요. 탈모 목적으로 이 제품을 5mg 그대로 복용하거나 임의로 나눠 먹는 건 허가 범위 밖이고요. 탈모라면 피나스테리드 1mg 처방약을 받아야 해요. 꾸준함이 중요하죠.",
