        answer:
          "피나진정5mg의 식약처 허가 적응증은 양성전립샘비대증이에요. 탈모 적응증은 허가사항에 없어요. 피나스테리드 성분은 1mg 함량으로 탈모 치료에 별도 허가를 받은 제품이 있어요. 탈모 목적이라면 피나스테리드 1mg 탈모 허가 제품을 의사에게 처방받아야 해요. 5mg 제품을 4등분·분할해 쓰는 방법은 허가 용법 밖이고 용량 편차가 생겨 안전성이 보장되지 않아요.",
