          "두타스테리드 0.5mg은 5알파환원효소 1형과 2형을 모두 억제해 혈중 DHT를 낮춰요. DHT는 모낭을 위축시켜 탈모를 진행시키는 물질이에요. 두 타입의 효소를 모두 막는다는 게 피나스테리드와의 핵심 차이죠.\n\n식약처 허가사항 기준 적응증은 명확해요. 양성 전립선 비대증의 치료(증상 개선, 급성 요저류 위험성 감소, 수술 필요성 감소)와 성인 남성(만 18~50세)의 남성형 탈모(androgenetic alopecia) 치료예요. 두 적응증 모두 식약처 허가를 받은 제품이라 전립선비대증 치료와 탈모 치료 목적 모두 처방받을 수 있어요.\n\n탈모 임상에서는 6개월 단위로 이상반응 빈도를 확인했어요. 효과 판단도 일정 기간 꾸준히 복용한 뒤에 이뤄지는 구조예요. 탈모 치료 목적으로 처방받을 때는 의사와 함께 치료 목표와 기간을 정하는 게 기본이에요.",
