          "허가 기준이 정한 투여 금기 대상은 세 가지예요. 여성, 18세 미만 소아, 그리고 이 약 성분이나 다른 5α-환원효소 억제제에 과민증이 있는 환자고요.\n\n신중히 투여해야 하는 경우도 명시돼 있어요. 임신을 계획하고 있는 성인 남성은 탈모 치료 목적으로 이 약을 쓸 때 생식능에 영향을 줄 수 있어 의사 판단하에 신중하게 결정해야 해요. 요잔류량이 크거나 중증 요류 감소가 나타나는 환자, 간장애 환자, 강력한 CYP3A4 억제제(예: 리토나비르)를 만성 투여하는 환자도 주의가 필요하죠.\n\n여성에게는 특별한 주의사항이 있어요. 이 약은 피부를 통해 흡수되기 때문에, 임신했거나 임신 가능성이 있는 여성이 취급해서는 안 돼요. 캡슐이 새어 피부에 닿으면 즉시 물과 비누로 씻어야 해요. 소아도 마찬가지로 누출되는 캡슐과의 접촉을 피해야 해요. 복용 중 헌혈은 마지막 복용 후 최소 6개월이 지날 때까지 금지예요.",
