          "탈모약을 찾다가 두타스테리드 0.5mg 제품을 처방받은 분이라면, 효과 범위를 먼저 확인해야 해요. 휴메리나연질캡슐의 식약처 허가사항 적응증은 두 가지예요. 첫째, 양성 전립선 비대증의 치료(증상 개선, 급성 요저류 위험성 감소, 수술 필요성 감소). 둘째, 성인 남성(만 18~50세)의 남성형 탈모(androgenetic alopecia)의 치료. 두 적응증이 같은 0.5mg 용량에 묶여 있죠.\n\n탈모 치료에서 허가 연령 상한이 50세라는 점이 중요해요. 식약처 허가 문서는 50세를 초과하는 남성형 탈모 환자에 대한 유효성 자료가 없다고 명시하고 있어요. 50세를 넘긴 상태라면 허가 범위 밖이라는 뜻이에요.\n\n전립선 목적이면 연령 상한이 다르게 적용돼요. 양성전립선 비대증 3상 임상시험은 47~94세 평균 66세의 피험자 4,300명 이상을 대상으로 진행됐고, 고령자와 젊은 환자 간 안전성·유효성 차이는 관찰되지 않았어요. 같은 약이어도 목적에 따라 허가 적용 기준이 달라지는 전문의약품이에요.",
