          "이 대목이 중요해요. 식약처 허가사항이 정한 금기가 명확하죠. 여성, 만 18세 미만 소아, 두타스테리드나 다른 5α-환원효소 억제제에 과민증이 있는 사람은 복용하면 안 돼요.\n\n경고 항목에서 중요한 점이 있어요. 이 약은 피부를 통해 흡수되기 때문에, 임신했거나 임신 가능성이 있는 여성은 약을 만지는 것도 안 돼요. 남자 태아의 외부 생식기 발달에 이상을 일으킬 수 있어서예요. 부서지거나 깨진 정제는 더 주의가 필요해요.\n\n임신을 계획 중인 남성도 생식능에 영향을 줄 수 있어서 의사 판단하에 신중히 복용해야 해요. 강력한 CYP3A4 억제제(예: 리토나비르)를 만성적으로 복용 중이라면 약물 상호작용 가능성이 있으니 처방 시 반드시 알려야 해요. 또 이 약을 복용 중이면 마지막 복용 후 최소 6개월이 지날 때까지 헌혈을 하면 안 돼요.",
